// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testFuzz_property(address sender, uint256 id, bytes calldata data) public {
        bool success;
        bytes memory retData;
        (success, retData) = address(c).call(abi.encodeWithSignature("onERC721Received(address,address,uint256,bytes)", sender, address(this), id, data));
        require(success, "call failed");
        bytes4 ret = abi.decode(retData, (bytes4));
        assertTrue(ret == 0x150b7a02);
    }
}
